template<typename Sink>
constexpr void forEachDeclaredEffect(TerminatorKind kind, Sink& sink)
{
    switch (kind) {
    case TerminatorKind::Jump: case TerminatorKind::Branch: case TerminatorKind::Switch: case TerminatorKind::Return: case TerminatorKind::ReturnCall:
    case TerminatorKind::Unreachable: case TerminatorKind::TestAndBranch:
        return;
    case TerminatorKind::SwitchString:
        sink.reads(MemoryLocation(AbstractHeap::StringStorage));
        sink.writes(MemoryLocation(AbstractHeap::StringStorage));
        sink.writes(MemoryLocation(AbstractHeap::RuntimeState));
        sink.throws();
        sink.collects();
        return;
    case TerminatorKind::Throw: case TerminatorKind::Rethrow:
        sink.throws();
        return;
    case TerminatorKind::SwitchOnShape:
        sink.reads(MemoryLocation(AbstractHeap::ShapeWords));
        return;
    case TerminatorKind::TryCallInline:
        sink.unknownCode();
        return;
    }
    RELEASE_ASSERT_NOT_REACHED_UNDER_CONSTEXPR_CONTEXT();
}

